import { useState, useEffect, type ChangeEvent, type FormEvent } from "react";
import axios from "axios";
import jsPDF from "jspdf";
import ExcelJS from "exceljs";

import autoTable from "jspdf-autotable";
import {
    listarCategoriasActivas,
    crearCategoria,
    actualizarCategoria,
    anularCategoria
} from "../services/categoriaServices";
import type { Categoria } from "../types/categoria";

const formInicial: Categoria = {
    idCategoria: null,
    nombre: "",
    descripcion: ""
};


const obtenerMensajeError = (error: unknown): string => {
    if (axios.isAxiosError(error)) {
        return error.response?.data?.mensaje ?? error.message;
    }
    if (error instanceof Error) {
        return error.message;
    }
    return "Ocurrió un error inesperado";
};
function Categorias() {
    const [categorias, setCategorias] = useState<Categoria[]>([]);
    const [form, setForm] = useState<Categoria>(formInicial);
    const [modoEdicion, setModoEdicion] = useState(false);
    const [mensaje, setMensaje] = useState("");


    const cargarCategorias = async () => {
        try {
            const respuesta = await listarCategoriasActivas();
            setCategorias(respuesta.data);
        } catch (error) {
            console.error("Error al listar categorías", error);
        }
    };

    useEffect(() => {
        cargarCategorias();
    }, []);

    const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setForm((prev) => ({ ...prev, [name]: value }));
    };
    const generarPDF = () => {
        const doc = new jsPDF();

        //  const doc = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });

        // 1. Título del reporte
        doc.setFontSize(18);
        doc.setFont("helvetica", "bold");

        doc.text("Listado de Categorías", 14, 15);
        doc.text("Fecha: " + new Date().toLocaleDateString(), 14, 25)
        doc.addImage("data:image/png;base64,", "PNG", 171, 10, 25, 25);
        // 2. Preparar los datos de la tabla
        const columnas = ["Nombre", "Descripción"];
        const filas = categorias.map((categoria) => [
            categoria.nombre,
            categoria.descripcion
        ]);

        // 3. Dibujar la tabla

        autoTable(doc, {

            head: [columnas],
            body: filas,
            startY: 40, // debajo de la fecha (y=25) y del logo (y=10 + alto 25)
            headStyles: { fillColor: [22, 101, 52], textColor: 255, fontSize: 12 },
            alternateRowStyles: { fillColor: [220, 252, 231] },
            styles: { fontSize: 10, cellPadding: 2 },
            columnStyles: { 0: { cellWidth: 60 } },
            theme: "grid"

        });

        const totalPaginas = doc.getNumberOfPages();

        for (let i = 1; i <= totalPaginas; i++) {
            doc.setPage(i);              // te posiciona en la página i
            doc.setFontSize(10);
            doc.setFont("helvetica", "normal");
            doc.text(
                `Página ${i} de ${totalPaginas}`,
                105,   // x: centro horizontal (210 / 2)
                290,   // y: cerca del borde inferior (A4 mide 297)
                { align: "center" }
            );
        }
        // 4. Descargar
        //  doc.save("categorias.pdf");
        return doc;
    };

    const exportarPDF = () => {
        const doc = generarPDF();
        doc.save("categorias.pdf");
    }

    const verPDF = () => {
        const doc = generarPDF();
        const url = doc.output("bloburl");
        window.open(url, "_blank");
    }
    const exportarExcel = async () => {
        // 1. Crear el libro y la hoja
        const libro = new ExcelJS.Workbook();
        const hoja = libro.addWorksheet("Categorías");

        // 2. Título y fecha
        hoja.addRow(["Listado de Categorías"]).font = { size: 16, bold: true };
        hoja.addRow(["Fecha: " + new Date().toLocaleDateString()]);
        hoja.addRow([]); // fila vacía de separación

        // 3. Encabezados de la tabla (mismos colores que el PDF)
        const encabezado = hoja.addRow(["Nombre", "Descripción"]);
        encabezado.eachCell((celda) => {
            celda.font = { bold: true, color: { argb: "FFFFFFFF" } };
            celda.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF166534" } };
            celda.border = { top: { style: "thin" }, left: { style: "thin" }, bottom: { style: "thin" }, right: { style: "thin" } };
        });

        // 4. Filas de datos
        categorias.forEach((categoria, indice) => {
            const fila = hoja.addRow([categoria.nombre, categoria.descripcion]);
            fila.eachCell((celda) => {
                celda.border = { top: { style: "thin" }, left: { style: "thin" }, bottom: { style: "thin" }, right: { style: "thin" } };
                // filas alternadas en verde claro, como en el PDF
                if (indice % 2 === 1) {
                    celda.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFDCFCE7" } };
                }
            });
        });

        // 5. Ancho de columnas
        hoja.getColumn(1).width = 30;
        hoja.getColumn(2).width = 60;

        // 6. Generar el archivo y descargarlo
        const buffer = await libro.xlsx.writeBuffer();
        const blob = new Blob([buffer], {
            type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        });
        const url = URL.createObjectURL(blob);
        const enlace = document.createElement("a");
        enlace.href = url;
        enlace.download = "categorias.xlsx";
        enlace.click();
        URL.revokeObjectURL(url);
    };
    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        try {
            if (modoEdicion && form.idCategoria !== null) {
                await actualizarCategoria(form.idCategoria, form);
                setMensaje("Categoría actualizada correctamente");
            } else {
                await crearCategoria(form);
                setMensaje("Categoría creada correctamente");
            }
            setForm(formInicial);
            setModoEdicion(false);
            cargarCategorias();
        } catch (error) {
            setMensaje(obtenerMensajeError(error));
            console.error("Error al guardar categoría", error);
        }
    };

    const handleModificar = (categoria: Categoria) => {
        setForm(categoria);
        setModoEdicion(true);
    };

    const handleAnular = async (idCategoria: number) => {
        const confirmar = window.confirm("¿Seguro que deseas anular esta categoría?");
        if (!confirmar) return;
        try {
            await anularCategoria(idCategoria);
            setMensaje("Categoría anulada correctamente");
            cargarCategorias();
        } catch (error) {
            setMensaje(obtenerMensajeError(error));
            console.error("Error al anular la categoría", error);
        }
    };
    return (
        <div className="min-h-screen bg-gray-100">
            <div className="p-10 font-times">
                <h2 className="p-10 text-2xl italic md:text-xl font-bold">Ingresar/Modificar Categorías</h2>
                {mensaje && <p>{mensaje}</p>}
                <form onSubmit={handleSubmit} >
                    <div className="columns-3">
                        <div>
                            <label htmlFor="nombre">Nombre:</label>
                            <input type="text" className="h-12 border border-gray-300" id="nombre" name="nombre" value={form.nombre} onChange={handleChange} />
                        </div>
                        <div>
                            <label htmlFor="descripcion">Descripción:</label>
                            <input type="text" className="h-12 border border-gray-300" id="descripcion" name="descripcion" value={form.descripcion} onChange={handleChange} />
                        </div>
                    </div>
                    <div className="p-10">
                        <button type="submit" className="p-10 h-12 animate-bounce bg-blue-500 hover:bg-sky-700 text-white font-bold py-2 px-4 rounded">
                            Guardar
                        </button>
                    </div>
                </form>
                <h2 className="h-12 text-2xl italic md:text-xl font-bold font-[Courier_New]">Listado de Categorías</h2>
                <button onClick={exportarPDF} className="p-2 bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded">
                    Exportar a PDF
                </button>
                <button onClick={verPDF} className="p-2 bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded">
                    Ver PDF
                </button>
                <button onClick={exportarExcel} className="ml-2 p-2 bg-emerald-600 hover:bg-emerald-800 text-white font-bold py-2 px-4 rounded">
                    Exportar a Excel
                </button>
                <table className="border-collapse:collapse; border: 1px solid black; width: 100%; margin-top: 20px;">
                    <thead>
                        <tr>
                            <th className="border border-gray-300">Nombre</th>
                            <th className="border border-gray-300">Descripción</th>
                            <th className="border border-gray-300">Modificar</th>
                            <th className="border border-gray-300">Eliminar</th>
                        </tr>
                    </thead>
                    <tbody>
                        {categorias.map((categoria) => (
                            <tr key={categoria.idCategoria}>
                                <td className="text-center border border-gray-300">{categoria.nombre}</td>
                                <td className="text-center border border-gray-300">{categoria.descripcion}</td>
                                <td className="text-center border border-gray-300">
                                    <button onClick={() => handleModificar(categoria)} className="animate-pulse transition bg-yellow-500 hover:bg-sky-700 text-white font-bold py-2 px-4 rounded">Modificar</button>
                                </td>
                                <td className="text-center border border-gray-300">
                                    <button onClick={() => categoria.idCategoria !== null && handleAnular(categoria.idCategoria)} className="animate-pulse bg-red-500 hover:bg-sky-700 text-white font-bold py-2 px-4 rounded">Eliminar</button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
export default Categorias;